{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="Integrative, playful, practical programs for people who want gentle systems for everyday wellbeing." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="theme-light">
  <svg aria-hidden="true" class="site-pattern" width="0" height="0" style="position:absolute;left:-9999px;">
    <defs>
      <pattern id="gridPattern" patternUnits="userSpaceOnUse" width="40" height="40">
        <rect width="40" height="40" fill="#f8fbfa"></rect>
        <path d="M0 40 L40 0 M0 0 L40 40" stroke="#eef7f6" stroke-width="0.6" opacity="0.8"/>
      </pattern>
    </defs>
  </svg>

  <header class="site-header">
    <div class="wrap">
      <a class="logo" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Main navigation">
        <button class="nav-toggle" aria-expanded="false" aria-controls="nav-list">Menu</button>
        <ul id="nav-list">
          <li><a href="services.html">Offerings</a></li>
          <li><a href="conditions.html">Conditions & Care</a></li>
          <li><a href="approach.html">My Way</a></li>
          <li><a href="about.html">About</a></li>
          <li><a href="pricing.html">Ways to Join</a></li>
          <li><a class="primary" href="book.html">Enroll</a></li>
        </ul>
      </nav>
      <div class="header-cta">
        <a class="phone" href="tel:{{PHONE}}">Call {{PHONE}}</a>
      </div>
    </div>
  </header>

  <main>
    <section class="hero reveal" id="hero">
      <div class="hero-inner wrap">
        <div class="hero-copy">
          <h1>{{BUSINESS_NAME}}</h1>
          <p class="lead">A playful, precise approach to whole-person resilience — short cohort cycles, practical tools, and gentle accountability.</p>
          <p class="tagline">{{TAGLINE}}</p>
          <div class="hero-actions">
            <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <button id="tryNowBtn" class="btn btn-ghost">Try it now — guided mini-exercise</button>
          </div>
        </div>
        <div class="hero-card">
          <svg class="card-pattern" viewBox="0 0 200 140" preserveAspectRatio="none" aria-hidden>
            <rect width="200" height="140" fill="url(#gridPattern)"></rect>
          </svg>
          <div class="card-content">
            <h3>Current cohort: Spring Cycle</h3>
            <p>Small-group rhythm: 8 weeks, weekly live sessions, practical takeaways you can use in the real world.</p>
            <a href="book.html" class="btn btn-outline">See next start dates</a>
          </div>
        </div>
      </div>
    </section>

    <section class="story reveal" id="story">
      <div class="wrap">
        <h2>Why this way?</h2>
        <p>We design short, actionable cohorts that fit into busy schedules. Think of it as an architectural sketch for your wellbeing — small structural changes that make each day easier, not grand promises of perfection.</p>
        <div class="masonry">
          <article class="card">
            <h3>Small groups, steady beats</h3>
            <p>Peer rhythm + curated lessons = better follow-through.</p>
          </article>
          <article class="card">
            <h3>Tools you can carry</h3>
            <p>Brief practices for breathing, sleep, mood, and focus — developed for real life.</p>
          </article>
          <article class="card">
            <h3>Evidence-friendly, human-first</h3>
            <p>We translate science into practical steps without clinical overpromises.</p>
          </article>
        </div>
      </div>
    </section>

    <section class="framework reveal" id="framework">
      <div class="wrap">
        <h2>How a cohort works</h2>
        <ol class="steps">
          <li>
            <strong>Orientation</strong>
            <p>Set a doable baseline and pick one change for the first 2 weeks.</p>
          </li>
          <li>
            <strong>Live group sessions</strong>
            <p>Guided practices, brief workshops, and a practical homework loop.</p>
          </li>
          <li>
            <strong>Personal check-ins</strong>
            <p>Short 1:1 options to adjust the plan to your context.</p>
          </li>
        </ol>
      </div>
    </section>

    <section class="offers reveal" id="offers">
      <div class="wrap">
        <h2>Programs</h2>
        <div class="offer-grid">
          <div class="offer">
            <h3>Foundations Cycle</h3>
            <p>8-week cohort for daily rhythm, sleep nudges, micro-practices for stress.</p>
            <a href="book.html" class="btn btn-sm">Join next cohort</a>
          </div>
          <div class="offer">
            <h3>Focus & Flow Lab</h3>
            <p>6-week practical experiments to sharpen attention, with accountability buddies.</p>
            <a href="book.html" class="btn btn-sm">Reserve a spot</a>
          </div>
          <div class="offer">
            <h3>Care Map Consult</h3>
            <p>One-time integrative planning session to chart priorities and next steps.</p>
            <a href="services.html" class="btn btn-sm">Learn more</a>
          </div>
        </div>
      </div>
    </section>

    <section class="pricing reveal" id="pricing">
      <div class="wrap">
        <h2>Ways to join</h2>
        <p>We offer cohort pricing, sliding options, and a la carte planning sessions. No hard promises—just clear participation terms and what's included.</p>
        <div class="pricing-grid">
          <div class="price-card">
            <h3>Cohort Access</h3>
            <div class="price">$599</div>
            <p>Full cohort package: weekly live sessions, recordings, community chat.</p>
            <a href="pricing.html" class="btn btn-outline">See payment options</a>
          </div>
          <div class="price-card">
            <h3>Mini Consult</h3>
            <div class="price">$120</div>
            <p>45-minute personalized mapping session.</p>
            <a href="booking.html" class="btn btn-outline">Book a consult</a>
          </div>
          <div class="price-card">
            <h3>Scholarships</h3>
            <div class="price">Varies</div>
            <p>Partial support available; apply during sign-up.</p>
            <a href="contact.html" class="btn btn-outline">Inquire</a>
          </div>
        </div>
      </div>
    </section>

    <section class="testimonials reveal" id="testimonials">
      <div class="wrap">
        <h2>Voices from cohorts</h2>
        <blockquote>
          "I liked the short, steady rhythm — felt doable and real. The small group kept me honest without pressure."
          <cite>— A cohort participant</cite>
        </blockquote>
      </div>
    </section>

    <section class="cta reveal" id="cta">
      <div class="wrap">
        <h2>Ready to try a small, steady system?</h2>
        <p>Sign up for an info session or try a short guided practice right here.</p>
        <div class="cta-actions">
          <a class="btn btn-primary" href="book.html">Join an info session</a>
          <button class="btn btn-ghost" id="tryNowBtn2">Try an on-page exercise</button>
        </div>
      </div>
    </section>
  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <address>{{CITY}}, {{STATE}}</address>
        <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>
      </div>
      <small>Educational resources and programs. Not a replacement for personalized medical advice.</small>
    </div>
  </footer>

  <div id="exerciseModal" class="modal" aria-hidden="true" role="dialog" aria-labelledby="exerciseTitle">
    <div class="modal-backdrop" data-close="true"></div>
    <div class="modal-panel" role="document">
      <button class="modal-close" aria-label="Close">×</button>
      <h3 id="exerciseTitle">Try a mini practice</h3>
      <div class="modal-body">
        <div class="exercise-chooser">
          <label><input type="radio" name="exercise" value="breath" checked> Breathing</label>
          <label><input type="radio" name="exercise" value="journal"> Journaling</label>
          <label><input type="radio" name="exercise" value="intention"> Intention</label>
        </div>
        <div id="exerciseArea"></div>
      </div>
    </div>
  </div>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
